export type { ChartDataItem } from "./types";
export {
  formatValue,
  getNumericValue,
  getNumericValueOrNull,
  calculateNiceTicks,
  getGridDasharray,
} from "./utils";
export { useContainerDimensions } from "./hooks";
export { ChartTooltip } from "./chart-tooltip";
export type {
  LineChartTooltipData,
  BarChartTooltipData,
  PieChartTooltipData,
  StackedBarChartTooltipData,
  FunnelChartTooltipData,
  TreemapChartTooltipData,
  RadarChartTooltipData,
  ScatterPlotTooltipData,
  HeatmapChartTooltipData,
  AreaChartTooltipData,
  GaugeChartTooltipData,
  WaterfallChartTooltipData,
  TooltipRenderer,
} from "./tooltip-types";

import type { ChartDataItem } from "./types";

export function formatValue(value: unknown): string {
  if (typeof value === "number") {
    if (Math.abs(value) >= 1_000_000) return `${(value / 1_000_000).toFixed(1)}M`;
    if (Math.abs(value) >= 1_000) return `${(value / 1_000).toFixed(1)}K`;
    return value.toLocaleString();
  }
  return String(value);
}

export function getNumericValue(
  data: ChartDataItem,
  key: keyof ChartDataItem
): number {
  const value = data[key];
  if (typeof value === "number" && isFinite(value)) return value;
  if (typeof value === "string") {
    const parsed = parseFloat(value.replace(/[,$%\s]/g, ""));
    if (isFinite(parsed)) return parsed;
  }
  return 0;
}

export function getNumericValueOrNull(
  data: ChartDataItem,
  key: keyof ChartDataItem
): number | null {
  const value = data[key];
  if (typeof value === "number" && isFinite(value)) return value;
  if (typeof value === "string") {
    const parsed = parseFloat(value.replace(/[,$%\s]/g, ""));
    if (isFinite(parsed)) return parsed;
  }
  return null;
}

export function calculateNiceTicks(min: number, max: number, count = 5): number[] {
  if (min === max) return [min];
  const range = max - min;
  const roughStep = range / (count - 1);
  const magnitude = Math.pow(10, Math.floor(Math.log10(roughStep)));
  const normalizedStep = roughStep / magnitude;
  let niceStep: number;
  if (normalizedStep <= 1) niceStep = magnitude;
  else if (normalizedStep <= 2) niceStep = 2 * magnitude;
  else if (normalizedStep <= 5) niceStep = 5 * magnitude;
  else niceStep = 10 * magnitude;
  const niceMin = Math.floor(min / niceStep) * niceStep;
  const niceMax = Math.ceil(max / niceStep) * niceStep;
  const ticks: number[] = [];
  for (let tick = niceMin; tick <= niceMax; tick += niceStep) {
    ticks.push(tick);
  }
  return ticks;
}

export function getGridDasharray(gridStyle: "solid" | "dashed" | "dotted"): string {
  switch (gridStyle) {
    case "solid": return "none";
    case "dotted": return "2 4";
    case "dashed":
    default: return "4 4";
  }
}

"use client";

import { useRef, useState } from "react";
import { useIsomorphicLayoutEffect } from "@/lib/hooks";

export function useContainerDimensions() {
  const ref = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(0);

  useIsomorphicLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    let rafId = 0;
    const update = () => {
      cancelAnimationFrame(rafId);
      rafId = requestAnimationFrame(() => setWidth(el.getBoundingClientRect().width));
    };
    update();
    const ro = new ResizeObserver(update);
    ro.observe(el);
    return () => {
      cancelAnimationFrame(rafId);
      ro.disconnect();
    };
  }, []);

  return [ref, width] as const;
}

import type { ReactNode } from "react";
import type { ChartDataItem } from "./types";

export type TooltipRenderer<D> = (data: D) => ReactNode;

export interface LineChartTooltipData<T extends ChartDataItem> {
  readonly label: string;
  readonly index: number;
  readonly series: readonly {
    readonly key: string;
    readonly value: number;
    readonly rawValue: unknown;
    readonly color: string;
  }[];
}

export interface BarChartTooltipData<T extends ChartDataItem> {
  readonly label: string;
  readonly value: number;
  readonly rawValue: unknown;
  readonly color: string;
  readonly index: number;
  readonly data: T;
}

export interface PieChartTooltipData<T extends ChartDataItem> {
  readonly label: string;
  readonly value: number;
  readonly rawValue: unknown;
  readonly percentage: number;
  readonly color: string;
  readonly index: number;
}

export interface StackedBarChartTooltipData<T extends ChartDataItem> {
  readonly label: string;
  readonly index: number;
  readonly segments: readonly {
    readonly key: string;
    readonly value: number;
    readonly color: string;
  }[];
  readonly total: number;
}

export interface FunnelChartTooltipData<T extends ChartDataItem> {
  readonly label: string;
  readonly value: number;
  readonly rawValue: unknown;
  readonly percentage: number;
  readonly conversionRate: number;
  readonly color: string;
}

export interface TreemapChartTooltipData {
  readonly name: string;
  readonly value: number;
  readonly formattedValue: string;
  readonly percentage: number;
  readonly path: readonly string[];
  readonly color: string;
}

export interface RadarChartTooltipData<T extends ChartDataItem> {
  readonly type: string;
  readonly seriesName: string;
  readonly axisLabel?: string;
  readonly value?: number;
  readonly formattedValue?: string;
  readonly color: string;
  readonly data: T;
}

export interface ScatterPlotTooltipData<T extends ChartDataItem> {
  readonly xValue: number;
  readonly yValue: number;
  readonly formattedX: string;
  readonly formattedY: string;
  readonly seriesKey?: string;
  readonly sizeValue?: number;
  readonly color: string;
}

export interface HeatmapChartTooltipData<T extends ChartDataItem> {
  readonly xLabel: string;
  readonly yLabel: string;
  readonly value: number;
  readonly formattedValue: string;
  readonly normalizedValue: number;
  readonly color: string;
}

export interface AreaChartTooltipData<T extends ChartDataItem> {
  readonly label: string;
  readonly index: number;
  readonly series: readonly {
    readonly key: string;
    readonly value: number;
    readonly rawValue: unknown;
    readonly color: string;
  }[];
}

export interface GaugeChartTooltipData {
  readonly value: number;
  readonly min: number;
  readonly max: number;
  readonly percentage: number;
  readonly unit?: string;
  readonly label?: string;
  readonly zone?: {
    readonly from: number;
    readonly to: number;
    readonly color: string;
    readonly label?: string;
  };
}

export interface WaterfallChartTooltipData<T extends ChartDataItem> {
  readonly label: string;
  readonly type: "increase" | "decrease" | "total";
  /** Signed delta for increase/decrease bars; the absolute value for totals. */
  readonly value: number;
  /** Running total after this step. */
  readonly cumulative: number;
  readonly color: string;
  readonly index: number;
  readonly data: T;
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

interface ChartTooltipProps {
  readonly visible: boolean;
  readonly x: number;
  readonly y: number;
  readonly children: React.ReactNode;
  readonly className?: string;
  readonly style?: React.CSSProperties;
}

export function ChartTooltip({ visible, x, y, children, className, style }: ChartTooltipProps) {
  const reduceMotion = useReducedMotion();

  return (
    <AnimatePresence>
      {visible && (
        <motion.div
          className={`absolute pointer-events-none z-50 bg-popover/98 backdrop-blur-md border border-border rounded-lg px-3 py-2.5 shadow-xl ${className ?? ""}`}
          style={{ left: x, top: y, ...(style as Record<string, unknown>) }}
          initial={{ opacity: 0, scale: reduceMotion ? 1 : 0.9 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: reduceMotion ? 1 : 0.9 }}
          transition={{ duration: reduceMotion ? 0 : 0.15, ease: "easeOut" }}
        >
          {children}
        </motion.div>
      )}
    </AnimatePresence>
  );
}
